class Solution {
    vector<pair<int,int>> emptyCells, sources;
    vector<int> excess;
    int ans;
    void dfs(int idx, int cost) {
        if (idx == (int)emptyCells.size()) {
            if (cost < ans) ans = cost;
            return;
        }
        for (int i = 0; i < (int)sources.size(); i++) {
            if (excess[i] > 0) {
                excess[i]--;
                int d = abs(emptyCells[idx].first - sources[i].first)
                      + abs(emptyCells[idx].second - sources[i].second);
                dfs(idx + 1, cost + d);
                excess[i]++;
            }
        }
    }
public:
    int minimumMoves(vector<vector<int>>& grid) {
        emptyCells.clear();
        sources.clear();
        for (int i = 0; i < 3; i++)
            for (int j = 0; j < 3; j++) {
                if (grid[i][j] == 0) emptyCells.push_back({i, j});
                else if (grid[i][j] > 1) sources.push_back({i, j});
            }
        excess.assign(sources.size(), 0);
        for (int i = 0; i < (int)sources.size(); i++)
            excess[i] = grid[sources[i].first][sources[i].second] - 1;
        ans = INT_MAX;
        dfs(0, 0);
        return ans;
    }
};
